/**
 * Fills EMPTY translation slots with machine translations made by LibreTranslate
 * (generated by `npm run i18n:autofill`, stored in ./translationsAuto.json).
 *
 * Hand-written translations always win: a slot is only filled when it is
 * missing or empty. Imported once at the very top of src/index.js so every
 * dictionary is complete before any component renders.
 */
import auto from './translationsAuto.json';
import { translations } from './translations';
import { pageTranslations } from './translationsPages';
import { translationsExtra, resourceI18n, businessI18n, buffI18n, contractI18n, transactionTypeI18n } from './translationsExtra';
import { BUSINESS_NAMES } from './businessNames';
import { RESOURCE_NAMES } from './resourceConfig';
import { TUTORIAL_UI, TUTORIAL_STEP_TEXTS } from './tutorialTranslations';
import { translationsMore } from './translationsMore';

const DICTS = {
  translations, pageTranslations, translationsExtra, resourceI18n, businessI18n,
  buffI18n, contractI18n, BUSINESS_NAMES, RESOURCE_NAMES, TUTORIAL_UI, TUTORIAL_STEP_TEXTS,
  translationsMore, transactionTypeI18n,
};

let applied = 0;

export function applyAutoTranslations(data = auto) {
  for (const [name, entries] of Object.entries(data || {})) {
    const root = DICTS[name];
    if (!root || !Array.isArray(entries)) continue;
    for (const [path, text] of entries) {
      if (!Array.isArray(path) || !path.length || typeof text !== 'string') continue;
      let node = root;
      for (let i = 0; i < path.length - 1; i += 1) {
        const k = path[i];
        if (node[k] === undefined || node[k] === null) node[k] = {};
        node = node[k];
        if (typeof node !== 'object') { node = null; break; }
      }
      const leaf = path[path.length - 1];
      if (node && !(typeof node[leaf] === 'string' && node[leaf].trim() !== '')) {
        node[leaf] = text;
        applied += 1;
      }
    }
  }
  return applied;
}

applyAutoTranslations();
